package slider.translation

import contracts.i18n.LanguageCatalog
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.junit.jupiter.params.ParameterizedTest
import org.junit.jupiter.params.provider.Arguments
import org.junit.jupiter.params.provider.MethodSource
import slider.DeckContext
import slider.SliderConfig.yamlMapper
import java.io.File
import java.util.stream.Stream

/**
 * Dogfooding unit test — validates the translated deck files generated by
 * `translateDeck` for the 3 demo decks (fr/en/ar).
 *
 * Each source deck was translated into the 21 other supported languages,
 * producing 63 `.adoc` files + 63 `deck-context.yml` files (126 total) in
 * `<repo-root>/slides/misc/`.
 *
 * The dogfood corpus is now derived from the live shared [LanguageCatalog]
 * (22 languages, talaria.school parity — BKY-LANG-22 S-217/S-225). The
 * target set for each source is every catalog code except the source itself.
 *
 * This test verifies:
 * - Every translated `.adoc` file exists and is non-empty.
 * - Every translated `.adoc` preserves AsciiDoc structure (title `=`, section `==`,
 *   speaker notes `[NOTE.speaker]`, at least one `[%step]` list).
 * - Every translated `deck-context.yml` parses and has the correct `languageCode`.
 * - The `outputFile` in each translated context points to the matching `.adoc`.
 */
class TranslatedDemoDeckTest {

    companion object {
        private val sourceCodes = listOf("fr", "en", "ar")

        /**
         * Target codes present in the committed dogfood corpus (BKY-LANG-22).
         * Derived from the live [LanguageCatalog] — the source language itself
         * is excluded so a source is never translated to itself.
         */
        private val dogfoodTargetCodes = LanguageCatalog.supportedCodes().sorted()

        @JvmStatic
        fun sourceTargetPairs(): Stream<Arguments> =
            sourceCodes.stream().flatMap { src ->
                dogfoodTargetCodes.stream()
                    .filter { it != src }
                    .map { tgt -> Arguments.of(src, tgt) }
            }

        @JvmStatic
        fun sourceCodesProvider(): Stream<Arguments> =
            sourceCodes.stream().map { Arguments.of(it) }
    }

    @ParameterizedTest
    @MethodSource("sourceTargetPairs")
    fun `translated adoc file should exist and be non-empty for each source-target pair`(
        source: String,
        target: String,
    ) {
        val adoc = translatedAdoc(source, target)
        assertThat(adoc.exists())
            .withFailMessage("Translated adoc not found: ${adoc.name}")
            .isTrue()
        assertThat(adoc.readText().trim().isNotEmpty())
            .withFailMessage("Translated adoc is empty: ${adoc.name}")
            .isTrue()
    }

    @ParameterizedTest
    @MethodSource("sourceTargetPairs")
    fun `translated adoc should preserve asciidoc structure with title and sections`(
        source: String,
        target: String,
    ) {
        val content = translatedAdoc(source, target).readText()
        assertThat(content).contains("=")
        assertThat(content).contains("==")
        assertThat(content).contains("[NOTE.speaker]")
        assertThat(content).contains("[%step]")
    }

    @ParameterizedTest
    @MethodSource("sourceTargetPairs")
    fun `translated adoc should preserve revealjs attributes`(
        source: String,
        target: String,
    ) {
        val content = translatedAdoc(source, target).readText()
        assertThat(content).contains(":revealjs_theme:")
        assertThat(content).contains(":revealjs_width:")
        assertThat(content).contains(":revealjs_height:")
    }

    @ParameterizedTest
    @MethodSource("sourceTargetPairs")
    fun `translated deck-context should parse with correct languageCode and matching outputFile`(
        source: String,
        target: String,
    ) {
        val ctx = translatedContext(source, target)
        assertThat(ctx.languageCode).isEqualTo(target)
        ctx.requireValidLanguage()

        val adoc = slidesMiscDir().resolve(ctx.outputFile)
        assertThat(adoc.exists())
            .withFailMessage("outputFile '${ctx.outputFile}' does not resolve to existing adoc")
            .isTrue()
    }

    @ParameterizedTest
    @MethodSource("sourceCodesProvider")
    fun `each source deck should have one translated adoc file per other language`(source: String) {
        val expected = dogfoodTargetCodes.count { it != source }
        val translated = slidesMiscDir().listFiles { f ->
            f.name.startsWith("capsule-feed-demo-${source}_") &&
                f.name.endsWith("-deck.adoc")
        } ?: emptyArray()
        assertThat(translated).hasSize(expected)
    }

    @ParameterizedTest
    @MethodSource("sourceCodesProvider")
    fun `each source deck should have one translated context file per other language`(source: String) {
        val expected = dogfoodTargetCodes.count { it != source }
        val translated = slidesMiscDir().listFiles { f ->
            f.name.startsWith("capsule-feed-demo-${source}_") &&
                f.name.endsWith("-deck-context.yml")
        } ?: emptyArray()
        assertThat(translated).hasSize(expected)
    }

    @Test
    fun `all translated adoc files should exist across all sources`() {
        val expected = sourceCodes.sumOf { src -> dogfoodTargetCodes.count { it != src } }
        val allAdoc = slidesMiscDir().listFiles { f ->
            f.name.matches(Regex("capsule-feed-demo-(fr|en|ar)_[a-z]{2}-deck\\.adoc"))
        } ?: emptyArray()
        assertThat(allAdoc).hasSize(expected)
    }

    @Test
    fun `all translated context files should exist across all sources`() {
        val expected = sourceCodes.sumOf { src -> dogfoodTargetCodes.count { it != src } }
        val allCtx = slidesMiscDir().listFiles { f ->
            f.name.matches(Regex("capsule-feed-demo-(fr|en|ar)_[a-z]{2}-deck-context\\.yml"))
        } ?: emptyArray()
        assertThat(allCtx).hasSize(expected)
    }

    @Test
    fun `rtl target decks should contain revealjs_direction rtl attribute`() {
        val rtlCodes = LanguageCatalog.ALL.filter { it.rtl }.map { it.code }
        assertThat(rtlCodes).contains("ar", "ur", "fa")
        sourceCodes.forEach { source ->
            rtlCodes.forEach { target ->
                if (source == target) return@forEach
                val content = translatedAdoc(source, target).readText()
                assertThat(content)
                    .withFailMessage("RTL deck $source→$target should have :revealjs_direction: rtl")
                    .contains(":revealjs_direction: rtl")
            }
        }
    }

    private fun translatedAdoc(source: String, target: String): File =
        slidesMiscDir().resolve("capsule-feed-demo-${source}_${target}-deck.adoc")

    private fun translatedContext(source: String, target: String): DeckContext {
        val file = slidesMiscDir().resolve("capsule-feed-demo-${source}_${target}-deck-context.yml")
        assertThat(file.exists())
            .withFailMessage("Translated context not found: ${file.name}")
            .isTrue()
        return yamlMapper.readValue(file, DeckContext::class.java)
    }

    private fun slidesMiscDir(): File =
        File(resolveRepoRoot(), "slides/misc")
            .takeIf { it.exists() }
            ?: File(resolveRepoRoot(), "foundry/public/slider-gradle/slides/misc")

    private fun resolveRepoRoot(): File {
        var dir = File(".").absoluteFile
        while (dir != null && dir.parentFile != null) {
            if (File(dir, "slides/misc/capsule-feed-demo-fr-deck.adoc").exists()) return dir
            if (File(dir, "foundry/public/slider-gradle/slides/misc/capsule-feed-demo-fr-deck.adoc").exists()) return dir
            dir = dir.parentFile
        }
        return File(".").absoluteFile
    }
}